/// One field of an engine-owned record.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct FieldDecl {
    pub name: &'static str,
    /// The column kind (components, resources) or the type (events).
    pub column: &'static str,
    /// The default value as JSON.
    pub default: &'static str,
    pub readonly: bool,
    pub tunable: bool,
    /// The meaningful range and Tune's increment; `None` when unstated.
    pub min: Option<f64>,
    pub max: Option<f64>,
    pub step: Option<f64>,
    /// A unit of the API's unit table, or empty.
    pub unit: &'static str,
    /// The person-facing name, or empty.
    pub label: &'static str,
    /// The field's docs, joined.
    pub doc: &'static str,
    /// An enum column's variants in index order; empty otherwise.
    pub variants: &'static [&'static str],
}

/// An engine-owned component, resource or event.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct RecordDecl {
    /// `component`, `resource` or `event`.
    pub kind: &'static str,
    /// The IDL name, the TypeScript token's name on `og`.
    pub name: &'static str,
    /// The schema name it registers under.
    pub schema: &'static str,
    pub fields: &'static [FieldDecl],
}

